// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.common.annotation.Experimental;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.QueryModelNode;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;

/** Writes packed-planner provenance after winner materialization. */
@Experimental
public final class CascadesPlanProvenanceAnnotator {

	private static final String EXACT_JOIN_SURFACE_PREFIX = "optimizer.exactJoinSurface";
	private static final String CASCADES_RULE = "optimizer.cascadesRule";
	private static final String CASCADES_RULE_KIND = "optimizer.cascadesRuleKind";
	private static final String CASCADES_PROOFS = "optimizer.cascadesProofs";
	private static final String CASCADES_REJECTIONS = "optimizer.cascadesRejectedAlternatives";
	private static final String PLANNED_CARDINALITY_Q_ERROR = "plannedCardinalityQError";
	private static final String PLANNED_COST_ROW_Q_ERROR_MAX = "plannedCostRowQErrorMax";
	private static final String PLANNED_COST_WORK_Q_ERROR_MAX = "plannedCostWorkQErrorMax";

	private CascadesPlanProvenanceAnnotator() {
	}

	public static void annotate(TupleExpr plan, PlanProvenance provenance) {
		annotate(plan, provenance, null);
	}

	public static void annotate(TupleExpr plan, PlanProvenance provenance, String plannerIdOverride) {
		if (plan == null || provenance == null) {
			return;
		}
		sanitizeSubtree(plan);
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr tupleExpr) {
					annotateIdentity(tupleExpr, provenance, plannerIdOverride);
				}
				node.visitChildren(this);
			}
		});
		annotateRoot(plan, provenance, plannerIdOverride);
		if (plan instanceof QueryRoot queryRoot && queryRoot.getArg() != null) {
			annotateRoot(queryRoot.getArg(), provenance, plannerIdOverride);
		}
		annotateCartesianWork(plan);
	}

	public static void sanitize(TupleExpr plan) {
		if (plan != null) {
			sanitizeSubtree(plan);
		}
	}

	private static void annotateIdentity(QueryModelNode node, PlanProvenance provenance, String plannerIdOverride) {
		EstimateSnapshot estimate = provenance.estimate();
		String plannerId = isBlank(plannerIdOverride) ? estimate.plannerId() : plannerIdOverride;
		node.setStringMetricPlanned(TelemetryMetricNames.PLANNER_ID, plannerId);
		setStringIfMissing(node, TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE, estimate.source());
		setStringIfMissing(node, TelemetryMetricNames.PLANNED_ESTIMATE_USAGE, estimate.usage());
		setStringIfMissing(node, TelemetryMetricNames.PLANNED_CARDINALITY_SHAPE, "vector");
		setStringIfMissing(node, TelemetryMetricNames.PLANNED_COST_SHAPE, "vector");
		node.setStringMetricPlanned(CASCADES_RULE, provenance.ruleId());
		node.setStringMetricPlanned(CASCADES_RULE_KIND, provenance.ruleKind().name());
		node.setStringMetricPlanned(CASCADES_PROOFS, proofSummary(provenance.proofs()));
		node.setStringMetricPlanned(CASCADES_REJECTIONS,
				rejectionSummary(provenance.rejectedAlternatives()));
	}

	private static void annotateRoot(QueryModelNode node, PlanProvenance provenance, String plannerIdOverride) {
		annotateIdentity(node, provenance, plannerIdOverride);
		EstimateSnapshot estimate = provenance.estimate();
		CostVector cost = provenance.cost();
		boolean originatingCostEvent = hasOriginatingCostEvent(node);
		for (Map.Entry<String, String> entry : estimate.stringMetrics().entrySet()) {
			if (!isExactJoinSurfaceMetric(entry.getKey())) {
				if (originatingCostEvent) {
					setStringIfMissing(node, entry.getKey(), entry.getValue());
				} else {
					node.setStringMetricPlanned(entry.getKey(), entry.getValue());
				}
			}
		}
		for (Map.Entry<String, Double> entry : estimate.doubleMetrics().entrySet()) {
			if (!isExactJoinSurfaceMetric(entry.getKey())) {
				if (originatingCostEvent) {
					setDoubleIfMissing(node, entry.getKey(), entry.getValue());
				} else {
					node.setDoubleMetricPlanned(entry.getKey(), entry.getValue());
				}
			}
		}
		node.setStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_DECISION_ID,
				provenance.ruleId() + ":g" + provenance.memoGroupId() + ":e" + provenance.expressionId());
		double plannedRows = finiteOr(cost.rows(), estimate.rows());
		double plannedWorkRows = finiteOr(cost.workRows(), estimate.workRows());
		if (!originatingCostEvent) {
			node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_CARDINALITY_ROWS, plannedRows);
			node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, plannedWorkRows);
			node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_WORK_ROWS, cost.workRows());
			node.setResultSizeEstimate(plannedRows);
			node.setCostEstimate(plannedWorkRows);
		}
		node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_OBJECTIVE_SCORE, cost.objectiveScore());
		node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_UNCERTAINTY_ROWS, cost.uncertaintyRows());
		node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_UNCERTAINTY_ROWS, cost.uncertaintyRows());
		node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_CARDINALITY_CONFIDENCE, cost.confidence());
		node.setDoubleMetricPlanned(PLANNED_CARDINALITY_Q_ERROR, cost.rowQErrorMax());
		node.setDoubleMetricPlanned(PLANNED_COST_ROW_Q_ERROR_MAX, cost.rowQErrorMax());
		node.setDoubleMetricPlanned(PLANNED_COST_WORK_Q_ERROR_MAX, cost.workQErrorMax());
		node.setDoubleMetricPlanned("plannedCascadesEvidenceCount", cost.evidenceCount());
	}

	private static boolean hasOriginatingCostEvent(QueryModelNode node) {
		double ordinal = node.getDoubleMetricPlanned("optimizer.costEventOrdinal");
		return Double.isFinite(ordinal) && ordinal > 0.0d
				&& !isBlank(node.getStringMetricPlanned("optimizer.costEventDigest"));
	}

	private static void sanitizeSubtree(TupleExpr root) {
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				removeExactJoinSurfaceMetrics(node);
				node.visitChildren(this);
			}
		});
	}

	private static void removeExactJoinSurfaceMetrics(QueryModelNode node) {
		try {
			node.removeStringMetricsPlannedIf(CascadesPlanProvenanceAnnotator::isExactJoinSurfaceMetric);
			node.getDoubleMetricsPlanned().keySet().removeIf(CascadesPlanProvenanceAnnotator::isExactJoinSurfaceMetric);
			node.getLongMetricsPlanned().keySet().removeIf(CascadesPlanProvenanceAnnotator::isExactJoinSurfaceMetric);
		} catch (UnsupportedOperationException ignored) {
			// Immutable no-op metric maps need no cleanup.
		}
	}

	private static void setStringIfMissing(QueryModelNode node, String metricName, String value) {
		if (isBlank(node.getStringMetricPlanned(metricName)) && !isBlank(value)) {
			node.setStringMetricPlanned(metricName, value);
		}
	}

	private static void setDoubleIfMissing(QueryModelNode node, String metricName, double value) {
		if (!Double.isFinite(node.getDoubleMetricPlanned(metricName)) && Double.isFinite(value)) {
			node.setDoubleMetricPlanned(metricName, value);
		}
	}

	private static boolean isExactJoinSurfaceMetric(String name) {
		return name != null && name.startsWith(EXACT_JOIN_SURFACE_PREFIX);
	}

	private static boolean isBlank(String value) {
		return value == null || value.isBlank();
	}

	private static double finiteOr(double value, double fallback) {
		return Double.isFinite(value) && value >= 0.0d ? value : fallback;
	}

	private static void annotateCartesianWork(TupleExpr plan) {
		List<TupleExpr> tupleNodes = new ArrayList<>();
		List<Join> joins = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr tupleExpr) {
					tupleNodes.add(tupleExpr);
				}
				if (node instanceof Join join) {
					joins.add(join);
				}
				node.visitChildren(this);
			}
		});
		Map<TupleExpr, Double> workByNode = new IdentityHashMap<>();
		for (TupleExpr tupleNode : tupleNodes) {
			workByNode.put(tupleNode, 0.0d);
		}
		for (Join join : joins) {
			double localWork = cartesianJoinWork(join);
			for (QueryModelNode ancestor = join; ancestor != null; ancestor = ancestor.getParentNode()) {
				if (ancestor instanceof TupleExpr tupleAncestor && workByNode.containsKey(tupleAncestor)) {
					workByNode.compute(tupleAncestor,
							(ignored, work) -> saturatedAdd(work == null ? 0.0d : work, localWork));
				}
			}
		}
		for (Map.Entry<TupleExpr, Double> entry : workByNode.entrySet()) {
			entry.getKey()
					.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_CARTESIAN_WORK_ROWS, entry.getValue());
		}
	}

	private static double cartesianJoinWork(Join join) {
		TupleExpr left = join.getLeftArg();
		TupleExpr right = join.getRightArg();
		if (!Collections.disjoint(left.getBindingNames(), right.getBindingNames())) {
			return 0.0d;
		}
		double leftRows = estimatedRows(left);
		double rightRows = estimatedRows(right);
		if (isBindinglessOneRowGuard(left, leftRows)) {
			return leftRows;
		}
		if (isBindinglessOneRowGuard(right, rightRows)) {
			return rightRows;
		}
		return saturatedMultiply(leftRows, rightRows);
	}

	private static boolean isBindinglessOneRowGuard(TupleExpr expression, double rows) {
		return rows <= 1.0d && expression instanceof StatementPattern pattern
				&& pattern.getVarList().stream().allMatch(variable -> variable.isAnonymous() || variable.hasValue());
	}

	private static double estimatedRows(TupleExpr expression) {
		double plannedRows = expression.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_COST_FINAL_ROWS);
		if (Double.isFinite(plannedRows) && plannedRows >= 0.0d) {
			return plannedRows;
		}
		double rows = expression.getResultSizeEstimate();
		return Double.isFinite(rows) && rows >= 0.0d ? rows : 1.0d;
	}

	private static double saturatedAdd(double left, double right) {
		double sum = left + right;
		return Double.isFinite(sum) && sum >= 0.0d ? sum : Double.MAX_VALUE;
	}

	private static double saturatedMultiply(double left, double right) {
		double product = left * right;
		return Double.isFinite(product) && product >= 0.0d ? product : Double.MAX_VALUE;
	}

	private static String proofSummary(List<RuleProof> proofs) {
		return proofs == null || proofs.isEmpty()
				? ""
				: proofs.stream().map(RuleProof::metricFragment).collect(Collectors.joining("; "));
	}

	private static String rejectionSummary(List<RejectedAlternative> rejections) {
		if (rejections == null || rejections.isEmpty()) {
			return "";
		}
		return rejections.stream()
				.map(rejection -> rejection.ruleId() + ':' + rejection.reason() + ":score="
						+ rejection.cost().objectiveScore())
				.collect(Collectors.joining("; "));
	}
}
